        num_q_heads % num_kv_heads == 0
        and head_dim % (2 * _VEC_WIDTH) == 0
        and _num_threads(num_q_heads, num_kv_heads, head_dim) <= _MAX_THREADS_PER_CTA
        and num_tokens * (num_q_heads + 2 * num_kv_heads) * head_dim < 2**31
